'use strict';
const icons={home:'<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1Z"/>',book:'<path d="M12 5C9 3 5 3 2 4v15c3-1 7-1 10 1 3-2 7-2 10-1V4c-3-1-7-1-10 1Zm0 0v15"/>',study:'<path d="m2 8 10-5 10 5-10 5Zm4 3v6c4 3 8 3 12 0v-6M22 8v8"/>',heart:'<path d="M20.8 4.6a5.4 5.4 0 0 0-7.6 0L12 5.8l-1.2-1.2a5.4 5.4 0 0 0-7.6 7.6L12 21l8.8-8.8a5.4 5.4 0 0 0 0-7.6Z"/>',note:'<path d="M13 4H4v17h16V11M16 3l5 5-9 9-5 1 1-5Z"/>',search:'<circle cx="10.5" cy="10.5" r="7.5"/><path d="m16 16 5 5"/>',check:'<path d="m5 12 4 4L19 6"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1 1m12 12 1 1M5 19l1-1M18 6l1-1"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4"/>'};
const icon=n=>`<svg class="ico" viewBox="0 0 24 24" aria-hidden="true">${icons[n]||icons.book}</svg>`;
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const norm=s=>s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
const months=['Janeiro','Fevereiro','Março','Abril','Maio','Junho','Julho','Agosto','Setembro','Outubro','Novembro','Dezembro'];
const themes=['Governo de si','Emoções e serenidade','Tempo e hábitos','Relacionamentos','Provações e esperança','Finanças e contentamento','Caráter e integridade','Sabedoria e aprendizagem','Serviço e comunidade','Mortalidade e esperança','Oração e transformação','Gratidão e legado'];
const nav=[['inicio','home','Início'],['devocionais','book','Devocionais'],['estudos','study','Estudos'],['biblia','book','Bíblia ARA'],['favoritos','heart','Favoritos'],['anotacoes','note','Anotações']];
const books=[['Gênesis','GEN',50],['Êxodo','EXO',40],['Levítico','LEV',27],['Números','NUM',36],['Deuteronômio','DEU',34],['Josué','JOS',24],['Juízes','JDG',21],['Rute','RUT',4],['1 Samuel','1SA',31],['2 Samuel','2SA',24],['1 Reis','1KI',22],['2 Reis','2KI',25],['1 Crônicas','1CH',29],['2 Crônicas','2CH',36],['Esdras','EZR',10],['Neemias','NEH',13],['Ester','EST',10],['Jó','JOB',42],['Salmo','PSA',150],['Provérbios','PRO',31],['Eclesiastes','ECC',12],['Cantares','SNG',8],['Isaías','ISA',66],['Jeremias','JER',52],['Lamentações','LAM',5],['Ezequiel','EZK',48],['Daniel','DAN',12],['Oseias','HOS',14],['Joel','JOL',3],['Amós','AMO',9],['Obadias','OBA',1],['Jonas','JON',4],['Miqueias','MIC',7],['Naum','NAM',3],['Habacuque','HAB',3],['Sofonias','ZEP',3],['Ageu','HAG',2],['Zacarias','ZEC',14],['Malaquias','MAL',4],['Mateus','MAT',28],['Marcos','MRK',16],['Lucas','LUK',24],['João','JHN',21],['Atos','ACT',28],['Romanos','ROM',16],['1 Coríntios','1CO',16],['2 Coríntios','2CO',13],['Gálatas','GAL',6],['Efésios','EPH',6],['Filipenses','PHP',4],['Colossenses','COL',4],['1 Tessalonicenses','1TH',5],['2 Tessalonicenses','2TH',3],['1 Timóteo','1TI',6],['2 Timóteo','2TI',4],['Tito','TIT',3],['Filemom','PHM',1],['Hebreus','HEB',13],['Tiago','JAS',5],['1 Pedro','1PE',5],['2 Pedro','2PE',3],['1 João','1JN',5],['2 João','2JN',1],['3 João','3JN',1],['Judas','JUD',1],['Apocalipse','REV',22]];
let data=[],page=1,query='',month='',statusFilter='',noteId=null,noteTimer,toastTimer,storageOK=true;
const defaultState=()=>({favorites:[],read:[],notes:[],theme:'light',font:0});
function validState(s){return s&&typeof s==='object'&&Array.isArray(s.favorites)&&s.favorites.every(n=>Number.isInteger(n)&&n>0&&n<=365)&&Array.isArray(s.read)&&s.read.every(n=>Number.isInteger(n)&&n>0&&n<=365)&&Array.isArray(s.notes)&&s.notes.length<=5000&&s.notes.every(n=>n&&typeof n.id==='string'&&typeof n.title==='string'&&typeof n.body==='string'&&typeof n.updated==='string'&&n.title.length<1000&&n.body.length<1000000)}
let state=defaultState();try{const old=JSON.parse(localStorage.getItem('fe365-v1'));if(validState(old))state={...state,...old};}catch(e){storageOK=false;}
function persist(){try{localStorage.setItem('fe365-v1',JSON.stringify(state));return true}catch(e){storageOK=false;toast('Não foi possível salvar neste navegador. Exporte um backup.');return false}}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3500)}
function settings(){document.body.classList.toggle('dark',state.theme==='dark');document.documentElement.style.setProperty('--reading',`${1.12+Math.min(3,Math.max(0,Number(state.font)||0))*.12}rem`)}settings();
const todayParts=new Intl.DateTimeFormat('en-CA',{timeZone:'America/Fortaleza'}).format(new Date()).split('-').map(Number);
const todayDate=new Date(todayParts[0],todayParts[1]-1,todayParts[2]);
const calendarIndex=(()=>{let m=todayDate.getMonth(),d=todayDate.getDate();if(m===1&&d===29)d=28;return Math.round((Date.UTC(2025,m,d)-Date.UTC(2025,0,1))/86400000)+1})();
$('#date-label').textContent=new Intl.DateTimeFormat('pt-BR',{weekday:'long',day:'numeric',month:'long'}).format(todayDate);
$('#search-shortcut').innerHTML=icon('search');
function bibleURL(ref){const m=ref.match(/^(.+?)\s+(\d+)(?::(\d+)(?:-(\d+))?)?/);if(!m)return 'https://www.bible.com/pt/bible/1608/GEN.1.ARA';const b=books.find(b=>norm(b[0])===norm(m[1])||(m[1]==='Salmos'&&b[1]==='PSA'));if(!b)return 'https://www.bible.com/pt/bible/1608/GEN.1.ARA';return `https://www.bible.com/pt/bible/1608/${b[1]}.${m[2]}${m[3]?'.'+m[3]+(m[4]?'-'+m[4]:''):''}.ARA`}
function devotionalImage(d,cardView=false){return `<img class="${cardView?'card-image':'devotional-image'}" src="${esc(d.image)}" alt="${esc(d.imageAlt)}" width="${d.imageWidth}" height="${d.imageHeight}" loading="${cardView?'lazy':'eager'}" decoding="async">`}
function card(d){return `<article class="card"><a class="card-image-link" href="#leitura/${d.id}" tabindex="-1" aria-hidden="true">${devotionalImage(d,true)}</a><p class="eyebrow">${esc(d.date)} · Dia ${d.id}</p><button class="fav-small ${state.favorites.includes(d.id)?'saved':''}" data-fav="${d.id}" aria-label="${state.favorites.includes(d.id)?'Remover dos':'Adicionar aos'} favoritos: ${esc(d.title)}" aria-pressed="${state.favorites.includes(d.id)}">${icon('heart')}</button><h3><a href="#leitura/${d.id}">${esc(d.title)}</a></h3><p>${esc(d.ref)}<br>${esc(themes[d.month-1])}${state.read.includes(d.id)?' · Lido':''}</p><a class="read" href="#leitura/${d.id}">Ler devocional</a></article>`}
function home(){const d=data[calendarIndex-1],count=new Set(state.read).size;const chosen=[d,...data.filter(x=>x.month===d.month&&x.id!==d.id)].slice(0,3);return `<section class="app-cover" aria-label="Capa do aplicativo"><img class="app-cover-image" src="images/capa.jpg" width="1186" height="1536" alt="Capa de 365 Dias de Sabedoria, Fé e Domínio Próprio, por Bergues Travassos" fetchpriority="high"><div class="app-cover-content"><p class="eyebrow">UM ENCONTRO DIÁRIO COM A PALAVRA</p><h1>Separe um tempo para a sua fé.</h1><p class="intro">Leia com calma. Converse com Deus. Leve a Palavra para o seu dia.</p><section class="hero" aria-label="Devocional de hoje"><span class="pill">DEVOCIONAL DE HOJE · DIA ${d.id}</span><h2>${esc(d.title)}</h2><p>${esc(d.ref)} · ${esc(themes[d.month-1])}</p><a class="primary" href="#leitura/${d.id}">${icon('book')} Ler a meditação de hoje</a></section></div></section><div class="stats"><div class="stat"><span>${icon('book')}</span><div><strong>${count}<small>devocionais lidos</small></strong></div></div><div class="stat"><span>${icon('heart')}</span><div><strong>${state.favorites.length}<small>leituras favoritas</small></strong></div></div><div class="stat"><span>${icon('note')}</span><div><strong>${state.notes.length}<small>anotações pessoais</small></strong></div></div></div><section class="two-col"><div class="quote-card"><p class="eyebrow">PARA GUARDAR NO CORAÇÃO</p><blockquote>${esc(d.sections[9].paragraphs[0])}</blockquote><small>Bergues Travassos · Meditação do dia</small></div><div class="progress-box"><p class="eyebrow">NO SEU RITMO</p><h3>Sua caminhada de leitura</h3><div class="progress-bar" role="progressbar" aria-label="Devocionais concluídos" aria-valuenow="${count}" aria-valuemin="0" aria-valuemax="365"><i style="width:${count/365*100}%"></i></div><p>${count} de 365 leituras concluídas.<br>Cada encontro com a Palavra tem seu valor.</p></div></section><div class="section-heading"><h2>Leituras para este mês</h2><a class="text-link" href="#devocionais">Ver os 365 devocionais</a></div><div class="cards home-cards">${chosen.map(card).join('')}</div><div class="section-heading"><h2>Continue seu momento com Deus</h2></div><div class="cards"><a class="panel" href="#biblia">${icon('book')}<h3 style="margin-top:16px">Leia a Bíblia ARA</h3><p class="result-meta">Escolha um livro e capítulo para abrir a leitura no YouVersion.</p></a><a class="panel" href="#estudos">${icon('study')}<h3 style="margin-top:16px">Aprofunde seu estudo</h3><p class="result-meta">Roteiros temáticos, contexto bíblico e questões para reflexão.</p></a><a class="panel" href="#anotacoes">${icon('note')}<h3 style="margin-top:16px">Registre o que aprendeu</h3><p class="result-meta">Seu espaço para orações, descobertas e decisões.</p></a></div>`}
function library(favorites=false){return `<p class="eyebrow">${favorites?'SEU ACERVO PESSOAL':'365 DIAS DE SABEDORIA, FÉ E DOMÍNIO PRÓPRIO'}</p><h1>${favorites?'Leituras que ficaram com você.':'Uma palavra para cada dia.'}</h1><p class="intro">${favorites?'Reencontre as meditações que você guardou.':'Devocionais de Bergues Travassos, organizados pelos doze meses do ano.'}</p><div class="toolbar"><label class="search">${icon('search')}<input id="q" aria-label="Buscar por palavra, tema ou passagem" placeholder="Buscar por palavra, tema ou passagem…" value="${esc(query)}" type="search"></label><select id="month" aria-label="Filtrar por mês"><option value="">Todos os meses</option>${months.map((m,i)=>`<option value="${i+1}" ${month==i+1?'selected':''}>${m}</option>`).join('')}</select><select id="read-filter" aria-label="Filtrar por leitura"><option value="">Todas as leituras</option><option value="unread" ${statusFilter==='unread'?'selected':''}>Ainda não li</option><option value="read" ${statusFilter==='read'?'selected':''}>Já li</option></select></div><div id="results"></div>`}
function results(){const fav=location.hash==='#favoritos';const tokens=norm(query).trim().split(/\s+/).filter(Boolean);let filtered=data.filter(d=>(!fav||state.favorites.includes(d.id))&&(!month||d.month===+month)&&(!statusFilter||(statusFilter==='read')===state.read.includes(d.id))&&tokens.every(t=>d.search.includes(t)));const pages=Math.max(1,Math.ceil(filtered.length/12));page=Math.min(page,pages);$('#results').innerHTML=`<p class="result-meta">${filtered.length} ${filtered.length===1?'devocional encontrado':'devocionais encontrados'}</p>${filtered.length?`<div class="cards">${filtered.slice((page-1)*12,page*12).map(card).join('')}</div><div class="pagination"><button class="secondary" id="prev" ${page===1?'disabled':''}>Anterior</button><span>${page} de ${pages}</span><button class="secondary" id="next" ${page===pages?'disabled':''}>Próxima</button></div>`:`<div class="empty">${icon(fav?'heart':'search')}<h2>${fav&&!query&&!month?'Você ainda não guardou uma leitura.':'Nenhuma leitura encontrada.'}</h2><p>${fav?'Use o coração nos devocionais para guardá-los aqui.':'Tente outra palavra ou remova os filtros.'}</p><a href="#devocionais" class="secondary">Ver devocionais</a></div>`}`;$('#prev')?.addEventListener('click',()=>{page--;results();$('#results').scrollIntoView({behavior:'smooth',block:'start'})});$('#next')?.addEventListener('click',()=>{page++;results();$('#results').scrollIntoView({behavior:'smooth',block:'start'})})}
function paragraphs(s){return s.paragraphs.map(t=>`<p>${esc(t)}</p>`).join('')}
function reader(id){const d=data[id-1];if(!d)return `<h1>Leitura não encontrada.</h1><a href="#devocionais">Ver devocionais</a>`;const read=state.read.includes(id);return `<article class="reader"><div class="reader-top"><a class="text-link" href="#devocionais">Todos os devocionais</a><span>${esc(d.date)} · Dia ${id} de 365</span></div>${devotionalImage(d)}<p class="eyebrow">${esc(themes[d.month-1])}</p><h1>${esc(d.title)}</h1><p class="byline">Por Bergues Travassos · ${esc(d.ref)}</p><div class="read-tools"><div class="actions"><button class="secondary ${state.favorites.includes(id)?'saved':''}" data-fav="${id}" aria-pressed="${state.favorites.includes(id)}">${icon('heart')} ${state.favorites.includes(id)?'Nos favoritos':'Favoritar'}</button><button class="secondary" id="note-from" data-id="${id}">${icon('note')} Anotar</button><a class="secondary" href="${bibleURL(d.ref)}" target="_blank" rel="noopener">Ler na ARA</a><button class="secondary" id="share">Compartilhar</button></div></div><div class="notice">Textos bíblicos desta meditação: JFA, edição de 1911, conforme o livro original. “Ler na ARA” abre a passagem no YouVersion em outra aba.</div><section class="reading-section scripture"><h2>Leitura bíblica</h2>${paragraphs(d.sections[0])}</section><section class="reading-section"><h2>Contexto bíblico</h2>${paragraphs(d.sections[1])}</section><section class="reading-section"><h2>Meditação</h2>${paragraphs(d.sections[2])}</section><details><summary>Diálogo com Sêneca e Marco Aurélio</summary><div class="reading-section">${paragraphs(d.sections[3])}</div></details><details><summary>Contribuições cristãs e comentários</summary><div class="reading-section">${paragraphs(d.sections[4])}<h2>Comentários e referências do livro</h2>${paragraphs(d.sections[5])}<p class="result-meta">As contribuições são apresentadas no livro como paráfrases. As aplicações editoriais pertencem à meditação.</p></div></details><section class="reading-section"><h2>Para praticar hoje</h2>${paragraphs(d.sections[6])}</section><section class="reading-section"><h2>Exame pessoal</h2>${paragraphs(d.sections[7])}</section><section class="reading-section prayer"><h2>Vamos orar</h2>${paragraphs(d.sections[8])}</section><section class="reading-section"><p class="eyebrow">FRASE PARA GUARDAR</p><div class="phrase">${paragraphs(d.sections[9])}</div></section><button class="primary" id="mark-read" data-id="${id}" aria-pressed="${read}">${icon('check')} ${read?'Leitura concluída':'Marcar como lido'}</button><div class="reader-end">${id>1?`<a class="secondary" href="#leitura/${id-1}">Dia ${id-1} · Leitura anterior</a>`:'<span></span>'}${id<365?`<a class="secondary" href="#leitura/${id+1}">Dia ${id+1} · Próxima leitura</a>`:''}</div><p class="notice">Fonte: livro “365 Dias de Sabedoria, Fé e Domínio Próprio”, de Bergues Travassos. Algumas reflexões descrevem as ilustrações presentes na edição original. <a class="text-link" href="#sobre">Sobre o conteúdo e suas fontes</a></p></article>`}
const studyPlans=[['Ouvir e praticar a Palavra','Comece pelo texto, leia os versículos próximos e identifique a resposta que o ensino pede.',[1,6,85],'Tiago 1:19-25','Qual é o ensino central da passagem e qual atitude sua precisa acompanhá-lo?'],['Domínio próprio e graça','Examine as decisões e os impulsos à luz da atuação de Deus em sua vida.',[2,14,28],'Gálatas 5:16-25','O que o texto diz sobre o fruto do Espírito e sua maneira de tratar as pessoas?'],['Ansiedade, oração e confiança','Apresente suas preocupações a Deus e considere o cuidado ensinado por Jesus.',[34,54,59],'Filipenses 4:4-9','Quais pedidos, agradecimentos e escolhas aparecem nessa passagem?'],['Descanso e fidelidade','Estude o descanso semanal com atenção ao mandamento e ao cuidado de Cristo.',[68,74,81],'Êxodo 20:8-11','Como o mandamento inclui as pessoas que vivem e trabalham com você?'],['Relacionamentos e perdão','Observe como escuta, verdade e responsabilidade participam da reconciliação.',[91,93,103],'Romanos 12:9-21','Quais atitudes do texto ajudam a interromper a vingança?'],['Esperança em meio à dor','Dê espaço ao lamento, à ajuda mútua e à confiança no Senhor durante as provações.',[123,129,130],'Salmo 13:1-6','Como a oração do salmista acolhe a dor e expressa confiança?'],['Contentamento e generosidade','Examine o lugar dos recursos, do trabalho e da partilha em sua vida.',[152,153,154],'1 Timóteo 6:6-10','Que diferença existe entre ter recursos e colocar neles sua segurança?'],['Integridade e serviço','Leia sobre caráter e liderança com os olhos voltados para a maneira como Jesus serviu.',[182,183,184],'Marcos 10:35-45','Como Jesus corrige a ideia de grandeza apresentada pelos discípulos?'],['Sabedoria que aprende','Considere a humildade necessária para receber instrução e rever uma escolha.',[213,214,215],'Tiago 1:5-8','Como o pedido de sabedoria se relaciona com a confiança em Deus?'],['Cuidado e comunidade','Procure o que a fé pede nas necessidades concretas de quem está perto de você.',[244,245,246],'Gálatas 6:1-10','Como ajudar alguém sem orgulho e sem abandonar a responsabilidade pessoal?'],['Ressurreição e esperança','Leia a promessa da volta de Cristo no contexto da esperança para os que morreram.',[274,275,276],'1 Tessalonicenses 4:13-18','Que esperança Paulo apresenta à comunidade enlutada?'],['Oração, gratidão e recomeço','Reúna o que aprendeu e apresente a Deus os compromissos do próximo dia.',[305,335,365],'Colossenses 4:2-6','Como oração, gratidão e cuidado com as palavras aparecem juntos?']];
function studies(){return `<p class="eyebrow">APRENDA COM A PALAVRA</p><h1>Estude com contexto e propósito.</h1><p class="intro">Doze roteiros temáticos com passagens bíblicas, perguntas e leituras do seu devocional.</p><div class="cards">${studyPlans.map((s,i)=>`<a class="card" href="#estudo/${i+1}"><span class="study-index">${icon('study')}</span><p class="eyebrow">ROTEIRO DE ESTUDO</p><h3>${esc(s[0])}</h3><p>${esc(s[1])}</p><span class="read">${esc(s[3])}</span></a>`).join('')}</div>`}
function study(id){const s=studyPlans[id-1];if(!s)return '<h1>Estudo não encontrado.</h1>';return `<article class="reader"><a class="text-link" href="#estudos">Todos os estudos</a><p class="eyebrow" style="margin-top:28px">ROTEIRO DE ESTUDO BÍBLICO</p><h1>${esc(s[0])}</h1><p class="intro">${esc(s[1])}</p><div class="panel"><p class="eyebrow">PASSAGEM PRINCIPAL</p><h2>${esc(s[3])}</h2><a class="primary" target="_blank" rel="noopener" href="${bibleURL(s[3])}">Ler a passagem na ARA</a></div><section class="reading-section"><h2>Leia e observe</h2><p>Leia a passagem inteira e os versículos próximos. Identifique quem fala, a quem se dirige e o assunto em discussão. Registre palavras que se repetem e dúvidas que precisam de esclarecimento.</p><h2>Reflita sobre o ensino</h2><p class="study-question">${esc(s[4])}</p><p>Ao anotar, separe o que o texto afirma da sua interpretação e da aplicação que você pretende praticar. Confira se a aplicação respeita o sentido da passagem.</p><h2>Aprofunde com estas leituras</h2></section><div class="cards" style="grid-template-columns:1fr">${s[2].map(id=>card(data[id-1])).join('')}</div><section class="reading-section"><h2>Leve o estudo para a vida</h2><p>Escolha uma atitude relacionada ao ensino que você identificou. Registre a decisão e ore com suas próprias palavras sobre o que aprendeu.</p><button class="primary" id="study-note" data-id="${id}">${icon('note')} Anotar meu estudo</button></section><div class="notice">Roteiro temático baseado em passagens bíblicas e nas leituras do livro. Para consultar a formulação das crenças adventistas, acesse <a class="text-link" href="https://institucional.adventistas.org/pt/nossas-crencas/" target="_blank" rel="noopener">Nossas crenças</a>.</div></article>`}
function bible(){return `<p class="eyebrow">BÍBLIA SAGRADA</p><h1>A Palavra, sempre por perto.</h1><p class="intro">Escolha seu livro e capítulo para ler a Almeida Revista e Atualizada no YouVersion.</p><div class="bible-layout"><section class="panel"><h2>O que você vai ler hoje?</h2><div class="book-row"><div><label for="book">Livro da Bíblia</label><select id="book">${books.map((b,i)=>`<option value="${i}">${esc(b[0]==='Salmo'?'Salmos':b[0])}</option>`).join('')}</select></div><div><label for="chapter">Capítulo</label><select id="chapter"></select></div></div><a id="open-bible" class="primary" target="_blank" rel="noopener">${icon('book')} Abrir capítulo na ARA</a><div class="notice">A leitura abre em outra aba no YouVersion. Este aplicativo não armazena nem reproduz a Bíblia ARA integral. É necessária conexão com a internet para acessar o serviço externo.</div><label for="bible-ref">Ou digite uma passagem</label><div class="search"><input id="bible-ref" placeholder="Ex.: João 3:16" aria-describedby="ref-help"><button id="go-ref" class="icon-btn" aria-label="Abrir passagem na ARA">${icon('search')}</button></div><p class="result-meta" id="ref-help" style="margin-top:10px">Use o nome completo do livro, capítulo e versículo.</p></section><aside class="bible-cover">${icon('book')}<p class="eyebrow" style="color:#d5be88">ALMEIDA REVISTA E ATUALIZADA</p><h2>Bíblia Sagrada</h2><p>Antigo e Novo Testamentos<br>Leitura pelo YouVersion</p></aside></div><div class="section-heading"><h2>Comece por aqui</h2></div><div class="cards">${[['O cuidado de Deus','Salmo 23:1-6'],['A vida de Jesus','João 1:1-18'],['A esperança da ressurreição','1 Tessalonicenses 4:13-18']].map(([t,r])=>`<a class="card" target="_blank" rel="noopener" href="${bibleURL(r)}"><h3>${t}</h3><p>${r}</p><span class="read">Ler na ARA · YouVersion</span></a>`).join('')}</div>`}
function createNote(title='Minha reflexão',body=''){const n={id:crypto.randomUUID(),title,body,updated:new Date().toISOString()};state.notes.unshift(n);noteId=n.id;persist();if(location.hash==='#anotacoes')render();else location.hash='anotacoes'}
function notes(){if(noteId&&!state.notes.some(n=>n.id===noteId))noteId=null;if(!noteId&&state.notes.length)noteId=state.notes[0].id;const n=state.notes.find(n=>n.id===noteId);return `<p class="eyebrow">SEU DIÁRIO DE FÉ</p><h1>Guarde o que Deus ensinou hoje.</h1><p class="intro">Reflexões, pedidos de oração e decisões. Um espaço para escrever com calma.</p><div class="actions"><button class="primary" id="new-note">${icon('note')} Nova anotação</button><button class="secondary" id="export">${icon('download')} Exportar backup</button><button class="secondary" id="import">Restaurar backup</button><input type="file" id="import-file" accept="application/json,.json" hidden></div><div class="notice">Suas anotações, favoritos e progresso ficam neste navegador e dispositivo. Não há sincronização entre aparelhos. Exporte um backup antes de limpar os dados do navegador ou trocar de aparelho. Em dispositivo compartilhado, outras pessoas com acesso ao navegador conseguem ver suas anotações.</div>${state.notes.length?`<div class="notes-layout"><div class="note-list">${state.notes.map(x=>`<button class="note-item ${x.id===noteId?'selected':''}" data-note="${esc(x.id)}"><strong>${esc(x.title||'Sem título')}</strong><small>${new Intl.DateTimeFormat('pt-BR',{day:'numeric',month:'short',year:'numeric'}).format(isNaN(Date.parse(x.updated))?new Date():new Date(x.updated))}</small></button>`).join('')}</div><section class="panel editor"><label for="note-title">Título</label><input type="text" maxlength="200" id="note-title" value="${esc(n.title)}"><label for="note-body" style="margin-top:16px">Sua anotação</label><textarea id="note-body" maxlength="200000" placeholder="O que chamou sua atenção na leitura?">${esc(n.body)}</textarea><div class="actions"><button class="primary" id="save-note">Salvar anotação</button><button class="secondary" id="delete-note">Excluir</button><span class="status" id="save-status">Salvo neste navegador</span></div></section></div>`:`<div class="empty" style="margin-top:24px">${icon('note')}<h2>Sua primeira anotação começa aqui.</h2><p>Escreva sobre uma passagem, uma oração ou uma decisão do dia.</p><button class="primary" data-new-note>Criar minha primeira anotação</button></div>`}`}
function saveNote(show=false){const n=state.notes.find(x=>x.id===noteId);if(!n||!$('#note-title'))return;clearTimeout(noteTimer);n.title=$('#note-title').value;n.body=$('#note-body').value;n.updated=new Date().toISOString();if(persist()){$('#save-status').textContent='Salvo neste navegador';const item=document.querySelector('[data-note="'+CSS.escape(noteId)+'"] strong');if(item)item.textContent=n.title||'Sem título';if(show)toast('Anotação salva.')}}
function about(){return `<article class="reader about"><p class="eyebrow">SOBRE O APLICATIVO</p><h1>365 • Fé para cada dia</h1><p>Leitura diária, estudo bíblico e espaço para refletir. O conteúdo dos 365 devocionais vem do livro “365 Dias de Sabedoria, Fé e Domínio Próprio”, de Bergues Travassos, na edição com capa disponível em seu acervo.</p><h2>Conteúdo e traduções</h2><p>As leituras preservam os textos do livro, incluindo o contexto, a meditação, o diálogo com os filósofos, os comentários, a aplicação e a oração. As cenas descritas são ilustrações editoriais. Cada leitura apresenta a imagem correspondente à abertura do mesmo dia no PDF original. As 365 imagens foram vinculadas pelo número do dia e pelo título do devocional.</p><p>JFA identifica a edição de João Ferreira de Almeida de 1911, na versão de leitura do projeto Bíblia Almeida, conforme informado no livro. Não é a ARA ou uma ARC contemporânea. Os comentários de autores são apresentados como paráfrases do livro, com as referências ali indicadas, e não como citações literais verificadas novamente para este aplicativo.</p><p>A Bíblia permanece o critério do diálogo com Sêneca e Marco Aurélio. A aproximação entre temas práticos não torna equivalentes o estoicismo e a fé cristã. As posições dos escritores cristãos citados não representam, em conjunto, a doutrina adventista.</p><p>A ARA é acessada por links externos para o YouVersion. O aplicativo não hospeda o texto integral da ARA. Sua reprodução integral dentro do aplicativo depende de autorização e integração com um provedor licenciado.</p><h2>Privacidade e seus dados</h2><p>Não há cadastro, anúncios ou ferramentas de análise adicionados pelo aplicativo. Favoritos, leituras concluídas, preferências e anotações são armazenados localmente neste navegador. Eles não são enviados pelo aplicativo para um banco de dados e não são sincronizados com outros aparelhos. O serviço de hospedagem e os sites externos têm suas próprias condições de uso e privacidade.</p><p>O armazenamento local não é um cofre com senha. Quem utiliza o mesmo perfil de navegador consegue acessar as anotações. A limpeza de dados do navegador remove os registros. Para preservar seu conteúdo, use o backup em Anotações. A restauração reúne o backup aos dados existentes e preserva as duas versões de anotações diferentes que tenham o mesmo identificador.</p><h2>Como usar</h2><p>Na tela inicial, a leitura acompanha a data do fuso de Fortaleza (UTC−3). O calendário tem 365 dias. Em 29 de fevereiro, o aplicativo apresenta a leitura de 28 de fevereiro. Use o coração para favoritar e o botão ao final da meditação para marcar como lida. O controle “Aa” aumenta o texto da meditação. O tema se alterna pelo botão abaixo.</p><div class="actions"><button class="secondary" id="about-theme">Alternar tema claro/escuro</button><a class="secondary" href="#anotacoes">Minhas anotações e backup</a></div><h2>Fontes do projeto</h2><a class="source-link" href="https://bibliaalmeida.com/" target="_blank" rel="noopener">Projeto Bíblia Almeida</a><a class="source-link" href="https://institucional.adventistas.org/pt/nossas-crencas/" target="_blank" rel="noopener">Crenças fundamentais da Igreja Adventista do Sétimo Dia</a><a class="source-link" href="https://www.sbb.org.br/biblia/ARA/JHN.3" target="_blank" rel="noopener">Sociedade Bíblica do Brasil: Almeida Revista e Atualizada</a><a class="source-link" href="https://www.bible.com/pt/bible/1608/GEN.1.ARA" target="_blank" rel="noopener">Leitura ARA no YouVersion</a><details id="source-details"><summary>Referências registradas no livro original</summary><div class="reading-section" id="sources-content">Abra para consultar as referências.</div></details><p class="notice">Aplicativo independente. Não se apresenta como aplicativo oficial da Igreja Adventista, da Sociedade Bíblica do Brasil ou do YouVersion.</p></article>`}
function render(){clearTimeout(noteTimer);const [rawRoute,param]=location.hash.slice(1).split('/');const route=rawRoute||'inicio';const active=route==='leitura'?'devocionais':route==='estudo'?'estudos':route;$('#nav').innerHTML=nav.map(([r,i,t])=>`<a href="#${r}" ${r===active?'class="active" aria-current="page"':''}>${icon(i)}<span>${t}</span></a>`).join('');const views={inicio:home,devocionais:()=>library(),favoritos:()=>library(true),leitura:()=>reader(+param),biblia:bible,estudos:studies,estudo:()=>study(+param),anotacoes:notes,sobre:about};$('#main').innerHTML=(views[route]||home)();document.title=`${({inicio:'Início',devocionais:'Devocionais',favoritos:'Favoritos',biblia:'Bíblia ARA',estudos:'Estudos',anotacoes:'Anotações',sobre:'Sobre',leitura:data[+param-1]?.title,estudo:studyPlans[+param-1]?.[0]})[route]||'365'} • Fé para cada dia`;
if(route==='devocionais'||route==='favoritos'){results();$('#q').addEventListener('input',e=>{query=e.target.value;page=1;results()});$('#month').addEventListener('change',e=>{month=e.target.value;page=1;results()});$('#read-filter').addEventListener('change',e=>{statusFilter=e.target.value;page=1;results()})}
if(route==='leitura'){$('#mark-read')?.addEventListener('click',e=>{let id=+e.currentTarget.dataset.id;state.read=state.read.includes(id)?state.read.filter(n=>n!==id):[...state.read,id];persist();const on=state.read.includes(id);e.currentTarget.innerHTML=icon('check')+(on?' Leitura concluída':' Marcar como lido');e.currentTarget.setAttribute('aria-pressed',on);toast(on?'Leitura marcada como concluída.':'Marcação removida.')});$('#note-from')?.addEventListener('click',()=>createNote(data[+param-1].title,`Leitura: ${data[+param-1].ref}\nDia ${param}\n\nMinha reflexão:\n`));$('#share')?.addEventListener('click',async()=>{const url=new URL(location.href);try{if(navigator.share)await navigator.share({title:data[+param-1].title,url:url.href});else{await navigator.clipboard.writeText(url.href);toast('Link copiado.')}}catch(e){if(e.name!=='AbortError')toast('Copie o endereço desta página para compartilhar.')}})}
if(route==='estudo')$('#study-note')?.addEventListener('click',()=>{const s=studyPlans[+param-1];createNote(s[0],`Estudo: ${s[3]}\n\n${s[4]}\n\nMinha reflexão:\n`) });
if(route==='biblia'){let b=0,c=1;try{const prev=JSON.parse(localStorage.getItem('fe365-bible'));if(prev&&books[prev.b]&&prev.c>=1&&prev.c<=books[prev.b][2]){b=prev.b;c=prev.c}}catch(e){}$('#book').value=b;function chapters(){const num=books[+$('#book').value][2];$('#chapter').innerHTML=Array.from({length:num},(_,i)=>`<option value="${i+1}">${i+1}</option>`).join('')}function bibleLink(){b=+$('#book').value;c=+$('#chapter').value;$('#open-bible').href=bibleURL(`${books[b][0]} ${c}`);try{localStorage.setItem('fe365-bible',JSON.stringify({b,c}))}catch(e){}}chapters();$('#chapter').value=c;bibleLink();$('#book').onchange=()=>{chapters();bibleLink()};$('#chapter').onchange=bibleLink;function goRef(){const ref=$('#bible-ref').value.trim(),m=ref.match(/^(.+?)\s+(\d+)(?::(\d+)(?:-(\d+))?)?$/);const book=m&&books.find(b=>norm(b[0])===norm(m[1])||(norm(m[1])==='salmos'&&b[1]==='PSA'));if(!book||+m[2]<1||+m[2]>book[2]||(m[3]&&+m[3]<1)||(m[4]&&+m[4]<+m[3])){toast('Confira a referência. Exemplo: João 3:16');return}window.open(bibleURL(ref),'_blank','noopener')}$('#go-ref').onclick=goRef;$('#bible-ref').onkeydown=e=>{if(e.key==='Enter')goRef()}}
if(route==='anotacoes'){$('#new-note').onclick=()=>{saveNote();createNote()};$('[data-new-note]')?.addEventListener('click',()=>createNote());$('#note-title')?.addEventListener('input',autosave);$('#note-body')?.addEventListener('input',autosave);$('#save-note')?.addEventListener('click',()=>saveNote(true));$('#delete-note')?.addEventListener('click',async()=>{const d=$('#confirm');d.showModal();d.addEventListener('close',()=>{if(d.returnValue==='delete'){clearTimeout(noteTimer);state.notes=state.notes.filter(n=>n.id!==noteId);noteId=null;persist();render();toast('Anotação excluída.')}},{once:true})});$('#export').onclick=()=>{saveNote();const blob=new Blob([JSON.stringify({app:'fe365',version:1,exportedAt:new Date().toISOString(),data:state},null,2)],{type:'application/json'});const u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=`365-fe-backup-${new Date().toISOString().slice(0,10)}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(u),5000);toast('Backup preparado para download.')};$('#import').onclick=()=>$('#import-file').click();$('#import-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;if(file.size>20*1024*1024){toast('O arquivo excede o limite de 20 MB.');return}try{const backup=JSON.parse(await file.text());if(backup.app!=='fe365'||backup.version!==1||!validState(backup.data))throw Error();saveNote();state.favorites=[...new Set([...state.favorites,...backup.data.favorites])];state.read=[...new Set([...state.read,...backup.data.read])];for(const note of backup.data.notes){const existing=state.notes.find(n=>n.id===note.id);if(!existing)state.notes.push({...note});else if(existing.title!==note.title||existing.body!==note.body)state.notes.push({...note,id:crypto.randomUUID(),title:note.title+' (backup)'})}if(persist()){render();toast('Backup restaurado. Seus registros foram reunidos.')}}catch(e){toast('Arquivo inválido. Use um backup exportado por este aplicativo.')}}}
if(route==='sobre'){$('#about-theme').onclick=toggleTheme;$('#source-details').addEventListener('toggle',async e=>{if(e.target.open&&!e.target.dataset.loaded){try{const r=await fetch('fontes.json');if(!r.ok)throw Error();const ps=await r.json();$('#sources-content').innerHTML=ps.map(t=>/^https:\/\//.test(t)?`<a class="source-link" target="_blank" rel="noopener" href="${esc(t)}">${esc(t)}</a>`:`<p>${esc(t)}</p>`).join('');e.target.dataset.loaded='1'}catch(e){$('#sources-content').textContent='Não foi possível carregar as referências. Tente novamente.'}}})}
}
function autosave(){$('#save-status').textContent='Salvando…';clearTimeout(noteTimer);noteTimer=setTimeout(()=>saveNote(),450)}
function toggleTheme(){state.theme=state.theme==='dark'?'light':'dark';settings();persist()}
$('#theme').onclick=toggleTheme;$('#font').onclick=()=>{state.font=((+state.font||0)+1)%4;settings();persist();toast(`Texto de leitura: ${['padrão','ampliado','grande','extra grande'][state.font]}`)};$('#search-shortcut').onclick=()=>{location.hash='devocionais';setTimeout(()=>$('#q')?.focus(),60)};
document.addEventListener('click',e=>{if(e.target.closest('.skip')){e.preventDefault();$('#main').focus();return}const f=e.target.closest('[data-fav]');if(f){const id=+f.dataset.fav;state.favorites=state.favorites.includes(id)?state.favorites.filter(n=>n!==id):[...state.favorites,id];persist();const on=state.favorites.includes(id);if(location.hash==='#favoritos')results();else{document.querySelectorAll(`[data-fav="${id}"]`).forEach(b=>{b.classList.toggle('saved',on);b.setAttribute('aria-pressed',on);if(b.classList.contains('secondary'))b.innerHTML=icon('heart')+(on?' Nos favoritos':' Favoritar');else b.setAttribute('aria-label',(on?'Remover dos':'Adicionar aos')+' favoritos: '+data[id-1].title)})}toast(on?'Devocional guardado nos favoritos.':'Devocional removido dos favoritos.')}const n=e.target.closest('[data-note]');if(n){saveNote();noteId=n.dataset.note;render()}const p=e.target.closest('[data-page]');if(p)location.hash=p.dataset.page});
window.addEventListener('hashchange',()=>{saveNote();render();window.scrollTo(0,0)});window.addEventListener('pagehide',()=>saveNote());
async function init(){try{const response=await fetch('devocionais.json');if(!response.ok)throw Error();data=await response.json();if(data.length!==365)throw Error();for(const d of data)d.search=norm([d.title,d.ref,themes[d.month-1],...d.sections.flatMap(s=>s.paragraphs)].join(' '));render();if(!storageOK)toast('Armazenamento indisponível. Use o backup para guardar seus registros.')}catch(e){$('#main').innerHTML='<div class="empty"><h1>Não foi possível carregar as leituras.</h1><p>Verifique sua conexão e tente novamente.</p><button class="primary" id="retry">Tentar novamente</button></div>';$('#retry').onclick=init}}
init();
